import json, sys, base64
import redis

host, port, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]
r = redis.Redis(host=host, port=port, decode_responses=False)

def b(x):
    if isinstance(x, bytes): return {"__b64__": base64.b64encode(x).decode()}
    if isinstance(x, (int, float, str)) or x is None: return x
    if isinstance(x, (list, tuple)): return [b(i) for i in x]
    if isinstance(x, dict): return {str(k): b(v) for k, v in x.items()}
    return str(x)

# discover non-empty dbs
dbs = []
for line in r.info("keyspace").values() if False else str(r.info("keyspace")).splitlines():
    pass
info = r.info("keyspace")
for name, val in info.items():
    if name.startswith("db"):
        dbs.append(int(name[2:]))
dbs = sorted(dbs)

snap = {"dbs": {}, "counts": {}}
for db in dbs:
    rc = redis.Redis(host=host, port=port, db=db, decode_responses=False)
    keys = sorted(k.decode() for k in rc.scan_iter(count=1000))
    snap["counts"][f"db{db}"] = len(keys)
    dbdata = {}
    for k in keys:
        t = rc.type(k).decode()
        pttl = rc.pttl(k)
        try:
            dmp = rc.dump(k)
        except Exception as e:
            dmp = None
        ent = {"type": t, "pttl": pttl, "dump": b(dmp)}
        if t == "string":
            ent["val"] = b(rc.get(k))
        elif t == "hash":
            h = rc.hgetall(k)
            ent["val"] = b(sorted([(f, v) for f, v in h.items()]))
        elif t == "list":
            ent["val"] = b(rc.lrange(k, 0, -1))
        elif t == "set":
            ent["val"] = b(sorted(rc.smembers(k)))
        elif t == "zset":
            ent["val"] = b(sorted(rc.zrange(k, 0, -1, withscores=True)))
        elif t == "stream":
            entries = rc.xrange(k, b"-", b"+")
            ent["entries"] = b([[eid, fields] for eid, fields in entries])
            gi = rc.xinfo_groups(k)
            groups = []
            for g in gi:
                gname = g[b"name"]
                pend = rc.xpending(k, gname)
                consumers = []
                for c in rc.xinfo_consumers(k, gname):
                    cp = rc.xpending_range(k, gname, b"-", b"+", count=100000, consumer=c[b"name"])
                    consumers.append({
                        "name": b(c[b"name"]),
                        "pending": b(sorted([[e[b"message_id"], e[b"delivery_count"]] for e in cp])),
                    })
                groups.append({
                    "name": b(gname),
                    "last_id": b(g[b"last-id"]),
                    "pel": b(g[b"pel"]),
                    "pending_ids": b(sorted([e[b"message_id"] for e in rc.xpending_range(k, gname, b"-", b"+", count=100000)])),
                    "consumers": sorted(consumers, key=lambda x: x["name"]["__b64__"] if isinstance(x["name"], dict) else str(x["name"])),
                })
            groups.sort(key=lambda x: x["name"]["__b64__"] if isinstance(x["name"], dict) else str(x["name"]))
            ent["groups"] = groups
            ent["info_len"] = b(rc.xlen(k))
        dbdata[k] = ent
    snap["dbs"][f"db{db}"] = dbdata

with open(out, "w") as f:
    json.dump(snap, f, indent=1, sort_keys=True)
print(f"snapshot written to {out}: dbs={snap['counts']}")
