import json, sys, time

a = json.load(open(sys.argv[1]))   # redis baseline
b = json.load(open(sys.argv[2]))   # valkey
TOL_MS = int(sys.argv[3]) if len(sys.argv) > 3 else 30000

errors = []
if a["counts"] != b["counts"]:
    errors.append(f"key counts differ: {a['counts']} vs {b['counts']}")

def isb(x): return isinstance(x, dict) and "__b64__" in x

for db in sorted(set(a["dbs"]) | set(b["dbs"])):
    da, dbv = a["dbs"].get(db, {}), b["dbs"].get(db, {})
    ka, kb = set(da), set(dbv)
    if ka - kb: errors.append(f"{db}: missing keys on valkey: {sorted(ka-kb)[:10]}")
    if kb - ka: errors.append(f"{db}: extra keys on valkey: {sorted(kb-ka)[:10]}")
    same_dump = diff_dump = 0
    for k in sorted(ka & kb):
        ea, eb = da[k], dbv[k]
        if ea["type"] != eb["type"]:
            errors.append(f"{db}:{k}: type {ea['type']} != {eb['type']}"); continue
        pa, pb = ea["pttl"], eb["pttl"]
        if pa == -1 or pb == -1:
            if pa != pb: errors.append(f"{db}:{k}: ttl flag {pa} != {pb}")
        elif abs(pa - pb) > TOL_MS:
            errors.append(f"{db}:{k}: pttl {pa} vs {pb} (diff {pa-pb}ms)")
        if ea.get("val") is not None and ea.get("val") != eb.get("val"):
            errors.append(f"{db}:{k}: value differs ({ea['type']})")
        for f in ("entries", "groups", "info_len"):
            if f in ea and ea[f] != eb.get(f):
                errors.append(f"{db}:{k}: stream field {f} differs")
        da_ = ea.get("dump"); db_ = eb.get("dump")
        if isb(da_) and isb(db_):
            if da_["__b64__"] == db_["__b64__"]:
                same_dump += 1
            else:
                # compare ignoring 3-byte footer (rdb ver + crc) 
                import base64
                xa, xb = base64.b64decode(da_["__b64__"]), base64.b64decode(db_["__b64__"])
                if xa[:-3] == xb[:-3]: same_dump += 1
                else:
                    diff_dump += 1
                    if diff_dump <= 5: errors.append(f"{db}:{k}: DUMP payload differs")
    print(f"{db}: keys compared={len(ka & kb)}, dump identical={same_dump}, dump differs={diff_dump}")

if errors:
    print(f"\n{len(errors)} DIFFERENCES:")
    for e in errors[:50]: print("  -", e)
    sys.exit(1)
print("\nALL CHECKS PASSED: key sets, types, values, TTLs, stream data/groups/PELs, DUMP payloads all match")
